package com.example.order.controller; import com.example.order.entity.Order; import com.example.order.repository.OrderRepository; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/orders") @CrossOrigin(origins="http://localhost:5173") public class OrderController { private final OrderRepository repo; private final KafkaTemplate<String,String> kafka; public OrderController(OrderRepository repo,KafkaTemplate<String,String> kafka){this.repo=repo;this.kafka=kafka;} @GetMapping public List<Order> all(){return repo.findAll();} @PostMapping public Order create(@RequestBody Order o){Order saved=repo.save(o); kafka.send("order.created","orderId="+saved.getId()); return saved;} }
